package com.citacloud.springboot.contacloud.app.services;
import com.citacloud.springboot.contacloud.app.dto.*;import com.citacloud.springboot.contacloud.app.models.*;import com.citacloud.springboot.contacloud.app.repositories.*;import com.citacloud.springboot.contacloud.app.security.*;
import org.springframework.data.domain.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.math.BigDecimal;import java.time.LocalDate;import java.util.*;
@Service public class AjusteInventarioService{
 private static final Set<Integer>SIZES=Set.of(10,25,50,100);private final AjusteInventarioRepository ajustes;private final LineaAjusteInventarioRepository lineas;private final MotivoAjusteInventarioRepository motivos;private final AlmacenRepository almacenes;private final ProductRepository productos;private final InventoryMovementRepository movimientos;private final InventoryMovementService movimientoService;private final AjusteInventarioNumeroService numeros;private final AuditoriaService auditoria;private final IdempotentOperationService idempotency;
 public AjusteInventarioService(AjusteInventarioRepository a,LineaAjusteInventarioRepository l,MotivoAjusteInventarioRepository m,AlmacenRepository w,ProductRepository p,InventoryMovementRepository im,InventoryMovementService ms,AjusteInventarioNumeroService n,AuditoriaService au,IdempotentOperationService idempotency){ajustes=a;lineas=l;motivos=m;almacenes=w;productos=p;movimientos=im;movimientoService=ms;numeros=n;auditoria=au;this.idempotency=idempotency;}
 @Transactional(readOnly=true)@PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('inventario_ajustes.ver')") public Page<AjusteInventarioDto> buscar(String q,LocalDate desde,LocalDate hasta,EstadoAjusteInventario estado,UUID almacen,TipoAjusteInventario tipo,UUID motivo,int page,int size){if(page<0||!SIZES.contains(size))throw new ReglaNegocioException("Paginación inválida.");if(desde!=null&&hasta!=null&&desde.isAfter(hasta))throw new ReglaNegocioException("La fecha inicial no puede ser posterior a la fecha final.");var p=TenantContext.principalActual();return ajustes.buscar(p.tenantId(),p.empresaId(),text(q).toLowerCase(Locale.ROOT),desde,hasta,estado,almacen,tipo,motivo,PageRequest.of(page,size,Sort.by(Sort.Direction.DESC,"fecha").and(Sort.by(Sort.Direction.DESC,"creadaEn")))).map(this::basico);}
 @Transactional(readOnly=true)@PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('inventario_ajustes.ver')")public AjusteInventarioDto obtener(UUID id){return completo(seguro(id,false));}
 @Transactional(readOnly=true)@PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('inventario_ajustes.ver')")public AjusteInventarioCatalogosDto catalogos(UUID almacenId){var p=TenantContext.principalActual();var ws=almacenes.findAllByTenantIdAndEmpresaIdAndActivoTrueOrderByNombre(p.tenantId(),p.empresaId()).stream().filter(w->!w.isAdministradoSistema()&&EmpresaContext.permiteSucursal(w.getSucursalId())).map(w->new AjusteInventarioCatalogosDto.Almacen(w.getId(),w.getNombre(),w.getSucursal().getNombre())).toList();var rs=motivos.findAllByTenantIdAndEmpresaIdAndActiveTrueOrderByName(p.tenantId(),p.empresaId()).stream().map(m->new AjusteInventarioCatalogosDto.Motivo(m.getId(),m.getCodigo(),m.getNombre(),m.getDireccion(),m.isRequiereObservacion())).toList();var ps=productos.findAllByTenantIdAndEmpresaIdAndActivoTrueAndControlaExistenciaTrueOrderByNombre(p.tenantId(),p.empresaId()).stream().filter(x->x.getTipo()==TipoProducto.PRODUCT).map(x->new AjusteInventarioCatalogosDto.Producto(x.getId(),x.getCodigo(),x.getNombre(),x.getUnidadMedidaId(),x.getUnidadMedida()==null?"Unidad":x.getUnidadMedida().getNombre(),almacenId==null?BigDecimal.ZERO:movimientos.saldo(p.tenantId(),p.empresaId(),almacenId,x.getId()),x.isPermiteExistenciaNegativa())).toList();return new AjusteInventarioCatalogosDto(ws,rs,ps);}
 @Transactional @PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('inventario_ajustes.crear')")public AjusteInventarioDto crear(AjusteInventarioInput input){Validado v=validar(input);var p=TenantContext.principalActual();AjusteInventario a=ajustes.saveAndFlush(new AjusteInventario(p.tenantId(),p.empresaId(),numeros.siguiente(p.tenantId(),p.empresaId()),v.fecha,v.almacen,v.motivo,v.referencia,v.observacion,v.tipo,p.usuarioId()));guardarLineas(a,v.productos);auditoria.registrar("INVENTORY_ADJUSTMENT_CREATED","INVENTORY_ADJUSTMENT",a.getId(),detalle(a));return completo(a);}
 @Transactional @PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('inventario_ajustes.editar')")public AjusteInventarioDto actualizar(UUID id,AjusteInventarioInput input){AjusteInventario a=seguro(id,true);if(a.getEstado()!=EstadoAjusteInventario.DRAFT)throw new ReglaNegocioException("Solo se puede editar un ajuste en borrador.");if(input.version()!=null&&input.version()!=a.getVersion())throw new ReglaNegocioException("El ajuste fue modificado por otro usuario. Actualiza la pantalla.");Validado v=validar(input);a.actualizar(v.fecha,v.almacen,v.motivo,v.referencia,v.observacion,v.tipo,TenantContext.principalActual().usuarioId());lineas.deleteAllByAjusteId(id);lineas.flush();guardarLineas(a,v.productos);ajustes.saveAndFlush(a);auditoria.registrar("INVENTORY_ADJUSTMENT_UPDATED","INVENTORY_ADJUSTMENT",id,detalle(a));return completo(a);}
 @Transactional @PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('inventario_ajustes.confirmar')")public AjusteInventarioDto confirmar(UUID id){AjusteInventario a=seguro(id,true);if(a.getEstado()==EstadoAjusteInventario.CONFIRMED||a.getEstado()==EstadoAjusteInventario.REVERSED)return completo(a);if(a.getEstado()!=EstadoAjusteInventario.DRAFT)throw new ReglaNegocioException("Solo se puede confirmar un ajuste en borrador.");var ls=lineas.findAllByAjusteIdOrderByProductoIdAscIdAsc(id);if(ls.isEmpty())throw new ReglaNegocioException("Agrega al menos un producto al ajuste.");var principal=TenantContext.principalActual();for(LineaAjusteInventario l:ls){Producto p=producto(l.getProductoId(),true);BigDecimal antes=movimientos.saldo(a.getTenantId(),a.getEmpresaId(),a.getAlmacenId(),p.getId());BigDecimal despues=antes.add(l.getCantidadBase());if(!p.isPermiteExistenciaNegativa()&&despues.signum()<0)throw new ReglaNegocioException("El ajuste dejaría existencias negativas para "+p.getNombre()+".");String dir=l.getCantidadBase().signum()>0?"IN":"OUT";movimientoService.ajustar(a,l,dir,dir.equals("IN")?"INVENTORY_ADJUSTMENT_IN":"INVENTORY_ADJUSTMENT_OUT",principal.usuarioId(),null);l.capturarSaldos(antes,despues);}a.confirmar(principal.usuarioId(),principal.nombre());auditoria.registrar("INVENTORY_ADJUSTMENT_CONFIRMED","INVENTORY_ADJUSTMENT",id,detalle(a));return completo(a);}
 @Transactional @PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('inventario_ajustes.confirmar') and (hasAuthority('inventario_ajustes.crear') or hasAuthority('inventario_ajustes.editar'))")public AjusteInventarioDto guardarYConfirmar(UUID id,AjusteInventarioInput input){Set<String> ps=TenantContext.principalActual().permisos();if(id==null&&!ps.contains("inventario_ajustes.crear"))throw new ReglaNegocioException("No tienes permiso para crear ajustes.");if(id!=null&&!ps.contains("inventario_ajustes.editar"))throw new ReglaNegocioException("No tienes permiso para editar ajustes.");var p=TenantContext.principalActual();String operation="INVENTORY_ADJUSTMENT_SAVE_AND_CONFIRM";if(id==null){var start=idempotency.begin(p.tenantId(),p.empresaId(),operation,input.claveOperacion(),fingerprint(input));if(start.replay())return completo(seguro(start.resultId(),false));}AjusteInventarioDto d=id==null?crear(input):actualizar(id,input);AjusteInventarioDto result=confirmar(d.id());if(id==null)idempotency.complete(p.tenantId(),p.empresaId(),operation,input.claveOperacion(),"AjusteInventario",d.id());return result;}
 @Transactional @PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('inventario_ajustes.anular')")public AjusteInventarioDto anular(UUID id,String razon){if(text(razon).isBlank())throw new ReglaNegocioException("El motivo de anulación es obligatorio.");AjusteInventario a=seguro(id,true);if(a.getEstado()==EstadoAjusteInventario.CANCELLED)return completo(a);if(a.getEstado()!=EstadoAjusteInventario.DRAFT)throw new ReglaNegocioException("Solo se puede anular un ajuste en borrador.");a.anular(razon.trim(),TenantContext.principalActual().usuarioId());auditoria.registrar("INVENTORY_ADJUSTMENT_CANCELLED","INVENTORY_ADJUSTMENT",id,detalle(a));return completo(a);}
 @Transactional @PreAuthorize("@empresaModuloService.habilitado('INVENTARIO') and hasAuthority('inventario_ajustes.revertir')")public AjusteInventarioDto revertir(UUID id,String razon){if(text(razon).isBlank())throw new ReglaNegocioException("El motivo de reversión es obligatorio.");AjusteInventario original=seguro(id,true);if(original.getEstado()==EstadoAjusteInventario.REVERSED)return completo(original);if(original.getEstado()!=EstadoAjusteInventario.CONFIRMED)throw new ReglaNegocioException("Solo se puede revertir un ajuste confirmado.");var p=TenantContext.principalActual();var originales=lineas.findAllByAjusteIdOrderByOrden(id);var movimientosOriginales=movimientos.findAllByTipoReferenciaAndReferenciaIdAndTenantIdAndEmpresaId("INVENTORY_ADJUSTMENT",id,p.tenantId(),p.empresaId());TipoAjusteInventario tipo=invertir(original.getTipo());AjusteInventario reverso=ajustes.saveAndFlush(new AjusteInventario(p.tenantId(),p.empresaId(),numeros.siguiente(p.tenantId(),p.empresaId()),LocalDate.now(),original.getAlmacen(),original.getMotivo(),original.getNumero(),"Reversión: "+razon,tipo,p.usuarioId()));reverso.establecerReversoDe(original.getId());int n=1;for(LineaAjusteInventario ol:originales){Producto producto=producto(ol.getProductoId(),true);LineaAjusteInventario nl=lineas.saveAndFlush(new LineaAjusteInventario(reverso,producto,ol.getCantidadAjuste().negate(),n++));BigDecimal antes=movimientos.saldo(p.tenantId(),p.empresaId(),reverso.getAlmacenId(),producto.getId());BigDecimal despues=antes.add(nl.getCantidadBase());if(!producto.isPermiteExistenciaNegativa()&&despues.signum()<0)throw new ReglaNegocioException("La reversión dejaría existencias negativas para "+producto.getNombre()+".");UUID movimientoOriginal=movimientosOriginales.stream().filter(x->Objects.equals(x.getLineaOrigenId(),ol.getId())).map(MovimientoInventario::getId).findFirst().orElse(null);String dir=nl.getCantidadBase().signum()>0?"IN":"OUT";movimientoService.ajustar(reverso,nl,dir,"INVENTORY_ADJUSTMENT_REVERSAL",p.usuarioId(),movimientoOriginal);nl.capturarSaldos(antes,despues);}reverso.confirmar(p.usuarioId(),p.nombre());original.marcarRevertido(reverso,p.usuarioId());auditoria.registrar("INVENTORY_ADJUSTMENT_REVERSED","INVENTORY_ADJUSTMENT",id,"{\"reversal\":\""+reverso.getNumero()+"\"}");return completo(original);}
 private Validado validar(AjusteInventarioInput i){if(i==null||i.fecha()==null)throw new ReglaNegocioException("La fecha es obligatoria.");Almacen w=almacen(i.almacenId());MotivoAjusteInventario m=motivo(i.motivoId());if(m.isRequiereObservacion()&&text(i.observacion()).isBlank())throw new ReglaNegocioException("Debe indicar la razón del ajuste.");if(i.lineas()==null||i.lineas().isEmpty())throw new ReglaNegocioException("Agrega al menos un producto al ajuste.");Set<String> unique=new HashSet<>();List<ProductoCantidad> ps=new ArrayList<>();boolean pos=false,neg=false;for(var l:i.lineas()){if(l==null||l.productoId()==null)throw new ReglaNegocioException("Selecciona un producto.");if(l.ajuste()==null||l.ajuste().signum()==0)throw new ReglaNegocioException("La cantidad del ajuste debe ser diferente de cero.");Producto p=producto(l.productoId(),false);if(!p.isActivo()||p.getTipo()!=TipoProducto.PRODUCT||!p.isControlaExistencia())throw new ReglaNegocioException("Solo se permiten productos inventariables.");if(l.unidadId()!=null&&!l.unidadId().equals(p.getUnidadMedidaId()))throw new ReglaNegocioException("La unidad seleccionada no corresponde al producto.");if(!unique.add(p.getId()+":"+p.getUnidadMedidaId()))throw new ReglaNegocioException("El producto ya fue agregado al ajuste.");if(!m.getDireccion().permite(l.ajuste().signum()))throw new ReglaNegocioException(m.getDireccion()==DireccionMotivoAjuste.OUT?"El motivo seleccionado solo permite ajustes de salida.":"El motivo seleccionado solo permite ajustes de entrada.");pos|=l.ajuste().signum()>0;neg|=l.ajuste().signum()<0;ps.add(new ProductoCantidad(p,l.ajuste()));}return new Validado(i.fecha(),w,m,clean(i.referencia()),clean(i.observacion()),pos&&neg?TipoAjusteInventario.MIXED:pos?TipoAjusteInventario.ENTRY:TipoAjusteInventario.EXIT,ps);}
 private void guardarLineas(AjusteInventario a,List<ProductoCantidad> ps){int n=1;for(var x:ps)lineas.save(new LineaAjusteInventario(a,x.producto,x.cantidad,n++));lineas.flush();}private Almacen almacen(UUID id){var p=TenantContext.principalActual();Almacen w=almacenes.findByIdAndTenantIdAndEmpresaId(id,p.tenantId(),p.empresaId()).orElseThrow(()->new RecursoNoEncontradoException("Almacén no encontrado."));if(!w.isActivo()||w.isAdministradoSistema())throw new ReglaNegocioException("El almacén seleccionado no está disponible.");if(!EmpresaContext.permiteSucursal(w.getSucursalId()))throw new ReglaNegocioException("No tienes acceso a la sucursal del almacén.");return w;}private MotivoAjusteInventario motivo(UUID id){var p=TenantContext.principalActual();return motivos.findByIdAndTenantIdAndEmpresaIdAndActiveTrue(id,p.tenantId(),p.empresaId()).orElseThrow(()->new RecursoNoEncontradoException("Motivo de ajuste no encontrado."));}private Producto producto(UUID id,boolean lock){var p=TenantContext.principalActual();return(lock?productos.bloquear(id,p.tenantId(),p.empresaId()):productos.findByIdAndTenantIdAndEmpresaId(id,p.tenantId(),p.empresaId())).orElseThrow(()->new RecursoNoEncontradoException("Producto no encontrado."));}private AjusteInventario seguro(UUID id,boolean lock){if(id==null)throw new RecursoNoEncontradoException("Ajuste no encontrado.");var p=TenantContext.principalActual();AjusteInventario a=(lock?ajustes.bloquear(id,p.tenantId(),p.empresaId()):ajustes.findByIdAndTenantIdAndEmpresaId(id,p.tenantId(),p.empresaId())).orElseThrow(()->new RecursoNoEncontradoException("Ajuste no encontrado."));if(!EmpresaContext.permiteSucursal(a.getAlmacen().getSucursalId()))throw new ReglaNegocioException("No tienes acceso al almacén de este ajuste.");return a;}
 private AjusteInventarioDto basico(AjusteInventario a){return dto(a,List.of());}private AjusteInventarioDto completo(AjusteInventario a){return dto(a,lineas.findAllByAjusteIdOrderByOrden(a.getId()));}private static AjusteInventarioDto dto(AjusteInventario a,List<LineaAjusteInventario> ls){String wh=first(a.getAlmacenHistorico(),a.getAlmacen().getNombre()),br=first(a.getSucursalHistorica(),a.getAlmacen().getSucursal().getNombre()),reason=first(a.getMotivoHistorico(),a.getMotivo().getNombre());return new AjusteInventarioDto(a.getId(),a.getNumero(),a.getFecha(),a.getAlmacenId(),wh,br,a.getMotivoId(),reason,a.getReferencia(),a.getObservacion(),a.getTipo(),a.getEstado(),a.getConfirmadaEn(),a.getConfirmadaPorNombre(),a.getAnuladaEn(),a.getMotivoAnulacion(),a.getRevertidaEn(),a.getRevertidaPorAjusteId(),a.getReversoDeId(),a.getVersion(),ls.stream().map(l->new AjusteInventarioDto.Linea(l.getId(),l.getProductoId(),l.getCodigoProducto(),l.getNombreProducto(),l.getUnidadId(),l.getUnidad(),l.getCantidadAjuste(),l.getSaldoAnterior(),l.getSaldoPosterior())).toList());}
 private static String fingerprint(AjusteInventarioInput i){return CommandFingerprint.sha256(new Object[]{i.fecha(),i.almacenId(),i.motivoId(),i.referencia(),i.observacion(),i.lineas()});}private static TipoAjusteInventario invertir(TipoAjusteInventario t){return t==TipoAjusteInventario.ENTRY?TipoAjusteInventario.EXIT:t==TipoAjusteInventario.EXIT?TipoAjusteInventario.ENTRY:TipoAjusteInventario.MIXED;}private static String text(String x){return x==null?"":x.trim();}private static String clean(String x){x=text(x);return x.isEmpty()?null:x;}private static String first(String x,String f){return x==null||x.isBlank()?f:x;}private static String detalle(AjusteInventario a){return "{\"numero\":\""+a.getNumero()+"\",\"estado\":\""+a.getEstado()+"\"}";}private record ProductoCantidad(Producto producto,BigDecimal cantidad){}private record Validado(LocalDate fecha,Almacen almacen,MotivoAjusteInventario motivo,String referencia,String observacion,TipoAjusteInventario tipo,List<ProductoCantidad> productos){}
}
